    "code": ".link {\n  position: relative;\n  color: #254d38;\n  text-decoration: none;\n  transition: color 180ms ease;\n}\n.link:hover { color: #bd572b; }\n.link::after {\n  content: \"\";\n  position: absolute;\n  left: 0; bottom: -4px;\n  width: 100%; height: 2px;\n  background: currentColor;\n  transform: scaleX(0);\n  transition: transform 180ms ease;\n}\n.link:hover::after { transform: scaleX(1); }"
